-- 38 Hex Strategy Board: a turn of a hex wargame. Where a piece can go is a
-- cheapest-first search over `Tilemap.neighbors` (six hexes, wherever the
-- row is pushed), who it can strike is `Tilemap.distance`, and red marches
-- with `Tilemap.find_path`. The board, its hexagons, the overlays and the
-- sorting of pieces among trees and mountains are the engine's.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/38-hex-strategy-board.scene"
local COLS, ROWS = 13, 8
local MOVE, ATTACK, PATH, SELECTED = 10, 11, 12, 13
local PINES, MOUNTAIN = 7, 8
-- Steps a hex costs by its ground (water: none - it cannot be entered).
local GROUND_COST = { 1, 1, 1, nil, 2, 2 }
local KINDS = {
    knight = { move = 3, range = 1, label = "knight" },
    archer = { move = 3, range = 3, label = "archer" },
    rider = { move = 5, range = 1, label = "rider" },
}
local UNITS = {
    { name = "Blue1", team = "blue", kind = "knight", c = 1, r = 3 },
    { name = "Blue2", team = "blue", kind = "archer", c = 0, r = 4 },
    { name = "Blue3", team = "blue", kind = "rider", c = 1, r = 5 },
    { name = "Blue4", team = "blue", kind = "knight", c = 2, r = 1 },
    { name = "Red1", team = "red", kind = "knight", c = 11, r = 3 },
    { name = "Red2", team = "red", kind = "archer", c = 12, r = 1 },
    { name = "Red3", team = "red", kind = "rider", c = 11, r = 5 },
    { name = "Red4", team = "red", kind = "knight", c = 9, r = 6 }
}
local STEP = 0.16

local post_on = nav.post_all_on(SCENE)
local captions = true
local map, status
local turn = "blue"
local selected, reach, parent
local hover_c, hover_r
local walking
local dying = {}
local ai_queue, ai_wait = nil, 0
local message = ""

local function key(c, r) return c * 100 + r end

local function set_status(text)
    message = text
    if status then UI.set_text(status, text) end
end

local function cell_pos(c, r)
    local x, y = Tilemap.tile_to_world(map, c, r)
    return x, y - 10
end

local function unit_at(c, r)
    for _, u in ipairs(UNITS) do
        if u.alive and u.c == c and u.r == r then return u end
    end
    return nil
end

local function cost_of(c, r)
    if c < 0 or r < 0 or c >= COLS or r >= ROWS then return nil end
    local thing = Tilemap.get_tile(map, "objects", c, r)
    if thing == MOUNTAIN then return nil end
    if thing == PINES then return 2 end
    return GROUND_COST[Tilemap.get_tile(map, "ground", c, r)]
end

-- Cheapest-first from the piece: every hex it can reach with its move,
-- through hexes no other piece stands on, and the hex each came from.
local function search(u, budget)
    local dist, from = {}, {}
    dist[key(u.c, u.r)] = 0
    local open = { { c = u.c, r = u.r, d = 0 } }
    while #open > 0 do
        local best = 1
        for i = 2, #open do
            if open[i].d < open[best].d then best = i end
        end
        local cur = table.remove(open, best)
        if cur.d <= dist[key(cur.c, cur.r)] then
            for _, n in ipairs(Tilemap.neighbors(map, cur.c, cur.r)) do
                local nc, nr = n[1], n[2]
                local cost = cost_of(nc, nr)
                if cost and not unit_at(nc, nr) then
                    local d = cur.d + cost
                    local k = key(nc, nr)
                    if d <= budget and (dist[k] == nil or d < dist[k]) then
                        dist[k] = d
                        from[k] = { cur.c, cur.r }
                        open[#open + 1] = { c = nc, r = nr, d = d }
                    end
                end
            end
        end
    end
    dist[key(u.c, u.r)] = nil
    return dist, from
end

local function in_range(u, v)
    return Tilemap.distance(map, u.c, u.r, v.c, v.r) <= KINDS[u.kind].range
end

local function path_to(c, r)
    local steps = {}
    local k = key(c, r)
    while parent and parent[k] do
        table.insert(steps, 1, { c, r })
        local p = parent[k]
        c, r = p[1], p[2]
        k = key(c, r)
    end
    return steps
end

local function draw_marks()
    for r = 0, ROWS - 1 do
        for c = 0, COLS - 1 do
            local m = 0
            if reach and reach[key(c, r)] then m = MOVE end
            Tilemap.set_tile(map, "marks", c, r, m)
        end
    end
    if not selected then return end
    if not selected.attacked then
        for _, v in ipairs(UNITS) do
            if v.alive and v.team ~= selected.team and in_range(selected, v) then
                Tilemap.set_tile(map, "marks", v.c, v.r, ATTACK)
            end
        end
    end
    if hover_c and reach and reach[key(hover_c, hover_r)] then
        for _, s in ipairs(path_to(hover_c, hover_r)) do
            Tilemap.set_tile(map, "marks", s[1], s[2], PATH)
        end
    end
    Tilemap.set_tile(map, "marks", selected.c, selected.r, SELECTED)
end

local function select_unit(u)
    selected = u
    reach, parent = nil, nil
    if u and not u.moved then
        reach, parent = search(u, KINDS[u.kind].move)
    end
    draw_marks()
    if u then
        set_status(KINDS[u.kind].label .. " - move " .. KINDS[u.kind].move .. ", reach " .. KINDS[u.kind].range)
    end
end

local function walk(u, steps, after)
    if #steps == 0 then
        if after then after() end
        return
    end
    walking = { u = u, steps = steps, i = 1, t = 0, after = after }
    local x, y = cell_pos(u.c, u.r)
    walking.fx, walking.fy = x, y
end

local function strike(u, v)
    u.attacked = true
    v.alive = false
    dying[#dying + 1] = { e = v.e, t = 0 }
    set_status(KINDS[u.kind].label .. " strikes the " .. v.team .. " " .. KINDS[v.kind].label)
end

local function reset_turn(team)
    for _, u in ipairs(UNITS) do
        if u.team == team then u.moved, u.attacked = false, false end
    end
end

local function alive_count(team)
    local n = 0
    for _, u in ipairs(UNITS) do
        if u.alive and u.team == team then n = n + 1 end
    end
    return n
end

-- Red's move: march at the nearest blue piece along `Tilemap.find_path`
-- (over the walls layer - water and mountains), stop where the next hex is
-- taken or the piece is in reach, and strike if it can.
local function red_move(u)
    local target, best
    for _, v in ipairs(UNITS) do
        if v.alive and v.team == "blue" then
            local d = Tilemap.distance(map, u.c, u.r, v.c, v.r)
            if best == nil or d < best then best, target = d, v end
        end
    end
    if not target then return end
    local function finish()
        if target.alive and in_range(u, target) then strike(u, target) end
    end
    if in_range(u, target) then
        finish()
        return
    end
    local path = Tilemap.find_path(map, "walls", u.c, u.r, target.c, target.r)
    local steps = {}
    if path then
        local budget = KINDS[u.kind].move
        local at = { c = u.c, r = u.r, kind = u.kind }
        for i = 2, #path do
            local c, r = path[i][1], path[i][2]
            local cost = cost_of(c, r)
            if cost == nil or cost > budget or unit_at(c, r) then break end
            budget = budget - cost
            steps[#steps + 1] = { c, r }
            at.c, at.r = c, r
            if Tilemap.distance(map, c, r, target.c, target.r) <= KINDS[u.kind].range then break end
        end
    end
    walk(u, steps, finish)
end

local function end_turn()
    select_unit(nil)
    draw_marks()
    turn = "red"
    set_status("red moves")
    ai_queue = {}
    for _, u in ipairs(UNITS) do
        if u.alive and u.team == "red" then ai_queue[#ai_queue + 1] = u end
    end
    ai_wait = 0.4
end

function init(entity)
    map = Entity.find_by_name("Board")
    status = Entity.find_by_name("Status")
    for _, u in ipairs(UNITS) do
        u.e = Entity.find_by_name(u.name)
        u.alive = u.e ~= nil
        u.moved, u.attacked = false, false
    end
    set_status("your turn - click a blue piece")
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("R") then Scene.load(SCENE) return end
    if map == nil then return end

    -- The struck fade and are gone.
    for i = #dying, 1, -1 do
        local d = dying[i]
        d.t = d.t + dt
        Sprite.set_color(d.e, 1, 0.4, 0.35, math.max(0, 1 - d.t / 0.4))
        if d.t >= 0.4 then
            Entity.destroy(d.e)
            table.remove(dying, i)
        end
    end

    -- A piece on the march, a hex at a time.
    if walking then
        local w = walking
        w.t = w.t + dt
        local s = w.steps[w.i]
        local tx, ty = cell_pos(s[1], s[2])
        local k = math.min(1, w.t / STEP)
        Transform.set_position(w.u.e, w.fx + (tx - w.fx) * k, w.fy + (ty - w.fy) * k)
        if k >= 1 then
            w.u.c, w.u.r = s[1], s[2]
            w.fx, w.fy = tx, ty
            w.t = 0
            w.i = w.i + 1
            if w.i > #w.steps then
                walking = nil
                if w.after then w.after() end
                if turn == "blue" and selected == w.u then select_unit(w.u) end
            end
        end
        return
    end

    if turn == "red" then
        ai_wait = ai_wait - dt
        if ai_wait > 0 then return end
        if ai_queue and #ai_queue > 0 then
            local u = table.remove(ai_queue, 1)
            if u.alive then red_move(u) end
            ai_wait = 0.25
        else
            turn = "blue"
            reset_turn("blue")
            if alive_count("blue") == 0 then set_status("red holds the field - R to play again")
            else set_status("your turn - click a blue piece") end
        end
        return
    end

    if Input.is_key_just_pressed("E") then
        end_turn()
        return
    end

    local wx, wy = Input.get_mouse_world_position()
    local c, r = Tilemap.world_to_tile(map, wx, wy)
    local on_board = c >= 0 and r >= 0 and c < COLS and r < ROWS
    if not on_board then c, r = nil, nil end
    if c ~= hover_c or r ~= hover_r then
        hover_c, hover_r = c, r
        if selected then draw_marks() end
    end

    if Input.is_mouse_left_just_pressed() and on_board then
        local there = unit_at(c, r)
        if there and there.team == "blue" then
            select_unit(there)
        elseif selected and there and there.team == "red" then
            if not selected.attacked and in_range(selected, there) then
                strike(selected, there)
                select_unit(selected)
                if alive_count("red") == 0 then set_status("the field is yours - R to play again") end
            end
        elseif selected and reach and reach[key(c, r)] then
            local u = selected
            local steps = path_to(c, r)
            u.moved = true
            reach, parent = nil, nil
            draw_marks()
            walk(u, steps, nil)
        else
            select_unit(nil)
            set_status("your turn - click a blue piece")
        end
    end
end
